import numpy as np,json,sys
from PIL import Image,ImageDraw
B=np.array([2.66969,-2.13364,.89794]); R=np.array([[0,-1,0],[1,0,0],[0,0,1]])
def cloud(path,cam):
 m=json.load(open(path+'/meta.json'))['cameras'][cam];K=np.array(m['intrinsic_cv']);T=np.array(m['cam2world_gl'])
 dep=np.load(path+'/depth_'+cam+'.npy')[-1].astype(float)
 v,u=np.indices(dep.shape)
 cv=np.stack([(u-K[0,2])*dep/K[0,0],(v-K[1,2])*dep/K[1,1],dep],-1)
 pts=(cv*np.array([1,-1,-1]))@T[:3,:3].T+T[:3,3]
 return pts, np.asarray(Image.open(path+'/last/'+cam+'.png'))
def point(path,cam,u,v):
 p,im=cloud(path,cam);x=p[v,u];print('pixel',u,v,'world',x,'base',R.T@(x-B));return x
if __name__=='__main__':
 path=sys.argv[1];cam=sys.argv[2]
 p,im=cloud(path,cam)
 if len(sys.argv)>3: point(path,cam,int(sys.argv[3]),int(sys.argv[4]))
 else:
  o=Image.fromarray(im).resize((960,720));d=ImageDraw.Draw(o)
  for u in range(0,320,20):d.line((u*3,0,u*3,720),fill='gray');d.text((u*3,0),str(u),fill='yellow')
  for v in range(0,240,20):d.line((0,v*3,960,v*3),fill='gray');d.text((0,v*3),str(v),fill='yellow')
  o.save(path+'/'+cam+'_grid.png')
